//! Launch at login (`[ui] launch_at_login`).
//!
//! The content of each platform's entry is generated by a pure function (tested everywhere);
//! [`apply`] writes or removes the real entry for the current OS:
//! - macOS: LaunchAgent plist `~/Library/LaunchAgents/io.zyno.siple.plist` (works unsigned and
//!   on macOS 12; `SMAppService` needs macOS 13 and a signed bundle);
//! - Windows: `HKCU\Software\Microsoft\Windows\CurrentVersion\Run`;
//! - Linux: `~/.config/autostart/io.zyno.siple.desktop` (XDG autostart);
//! - Flatpak: the Background portal (`portal_background`), which writes that entry on the host.

// Windows only writes a registry value; the file-based entries are built (and tested) everywhere.
#![cfg_attr(target_os = "windows", allow(dead_code))]

use std::path::{Path, PathBuf};

use siple_core::config::APP_ID;

/// Escapes text for an XML plist `<string>`.
fn xml_escape(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

/// LaunchAgent plist that runs `args` (program first) at login.
pub fn macos_launch_agent(label: &str, args: &[String]) -> String {
    let items: String = args
        .iter()
        .map(|a| format!("        <string>{}</string>\n", xml_escape(a)))
        .collect();
    format!(
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n\
         <!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n\
         <plist version=\"1.0\">\n\
         <dict>\n\
         \x20   <key>Label</key>\n\
         \x20   <string>{}</string>\n\
         \x20   <key>ProgramArguments</key>\n\
         \x20   <array>\n{items}\x20   </array>\n\
         \x20   <key>RunAtLoad</key>\n\
         \x20   <true/>\n\
         \x20   <key>KeepAlive</key>\n\
         \x20   <false/>\n\
         \x20   <key>ProcessType</key>\n\
         \x20   <string>Interactive</string>\n\
         \x20   <key>LimitLoadToSessionType</key>\n\
         \x20   <string>Aqua</string>\n\
         </dict>\n\
         </plist>\n",
        xml_escape(label),
    )
}

/// Program arguments for the macOS LaunchAgent: `open -a <bundle>` inside an app bundle (so
/// LaunchServices starts it like a double click), else the executable itself. `extra` (for
/// example `--config <path>` of a non-default profile) follows.
pub fn macos_program_args(exe: &Path, extra: &[String]) -> Vec<String> {
    let s = exe.to_string_lossy();
    let mut v = if let Some(i) = s.find(".app/Contents/MacOS/") {
        let mut v = vec!["/usr/bin/open".into(), "-a".into(), s[..i + 4].to_string()];
        if !extra.is_empty() {
            v.push("--args".into());
        }
        v
    } else {
        vec![s.into_owned()]
    };
    v.extend(extra.iter().cloned());
    v
}

/// Extra arguments that make the login item start this profile: `--config <path>` when it is
/// not the default one.
pub fn profile_args(config: Option<&Path>) -> Vec<String> {
    config.map_or_else(Vec::new, |c| {
        vec!["--config".into(), c.to_string_lossy().into_owned()]
    })
}

/// Quotes one argument of a Desktop Entry `Exec=` line (spec: wrap in double quotes when it has
/// spaces or reserved characters; escape `"`, `` ` ``, `$` and `\`; `%` doubles).
pub fn desktop_exec_quote(arg: &str) -> String {
    let reserved = " \t\n\r\"'\\><~|&;$*?#()`";
    if !arg.chars().any(|c| reserved.contains(c) || c == '%') {
        return arg.to_string();
    }
    // Two layers: the Exec quoting (`\` before `"`, `` ` ``, `$`, `\`) and then the string
    // escaping of the key's value, which doubles every backslash again.
    let mut out = String::from("\"");
    for c in arg.chars() {
        match c {
            '"' | '`' | '$' => {
                out.push_str("\\\\");
                out.push(c);
            }
            '\\' => out.push_str("\\\\\\\\"),
            '%' => out.push_str("%%"),
            // String escapes, so a path can never start a new key line.
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}

/// XDG autostart entry.
pub fn linux_autostart_entry(exe: &Path, extra: &[String]) -> String {
    let mut exec = desktop_exec_quote(&exe.to_string_lossy());
    for a in extra {
        exec.push(' ');
        exec.push_str(&desktop_exec_quote(a));
    }
    format!(
        "[Desktop Entry]\n\
         Type=Application\n\
         Name=Siple\n\
         Comment=Start Siple when you log in\n\
         Exec={exec}\n\
         Icon={}\n\
         Terminal=false\n\
         X-GNOME-Autostart-enabled=true\n",
        super::ICON_NAME
    )
}

/// Value of the Windows `Run` entry.
#[cfg_attr(not(target_os = "windows"), allow(dead_code))]
pub fn windows_run_value(exe: &Path, extra: &[String]) -> String {
    let mut v = format!("\"{}\"", exe.to_string_lossy());
    for a in extra {
        v.push_str(&format!(" \"{}\"", a.replace('"', "")));
    }
    v
}

/// Name of this profile's login entry (file stem / `Run` value name): the plain app id for the
/// default profile, the id plus 8 hex digits of a hash of the config path otherwise, so profiles
/// never share (or delete) each other's entry.
pub fn entry_name(config: Option<&Path>) -> String {
    match config {
        None => APP_ID.to_string(),
        Some(c) => {
            // FNV-1a: stable across runs and platforms (it names a file).
            let mut h: u32 = 0x811c_9dc5;
            for b in c.to_string_lossy().bytes() {
                h ^= u32::from(b);
                h = h.wrapping_mul(0x0100_0193);
            }
            format!("{APP_ID}-{h:08x}")
        }
    }
}

/// Where the entry file lives (macOS, Linux). `None` when the directory is unknown.
pub fn entry_path(
    home: Option<&Path>,
    config_dir: Option<&Path>,
    macos: bool,
    name: &str,
) -> Option<PathBuf> {
    if macos {
        home.map(|h| h.join("Library/LaunchAgents").join(format!("{name}.plist")))
    } else {
        config_dir.map(|c| c.join("autostart").join(format!("{name}.desktop")))
    }
}

/// Writes `content` unless the file already holds it; creates parent directories.
fn write_if_changed(path: &Path, content: &str) -> std::io::Result<()> {
    if std::fs::read_to_string(path).is_ok_and(|c| c == content) {
        return Ok(());
    }
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir)?;
    }
    std::fs::write(path, content)
}

/// Whether `content` is a login entry written by the Flatpak edition's Background portal
/// (xdg-desktop-portal writes `X-Flatpak=<app id>` and `Exec=flatpak run ...`). The tarball
/// shares that file name (`io.zyno.siple.desktop`), so it must leave such an entry alone.
fn is_flatpak_entry(content: &str) -> bool {
    content.lines().map(str::trim).any(|l| {
        l.starts_with("X-Flatpak=")
            || l.starts_with("X-Flatpak-")
            || l.strip_prefix("Exec=")
                .is_some_and(|e| e.trim_start().starts_with("flatpak run"))
    })
}

/// True when `path` holds the Flatpak edition's entry (logged once per process).
fn owned_by_flatpak(path: &Path) -> bool {
    static LOGGED: std::sync::Once = std::sync::Once::new();
    let owned = std::fs::read_to_string(path).is_ok_and(|c| is_flatpak_entry(&c));
    if owned {
        LOGGED.call_once(|| {
            tracing::info!(
                path = %path.display(),
                "the login entry belongs to the Flatpak edition; leaving it alone"
            );
        });
    }
    owned
}

/// [`write_if_changed`] that never overwrites the Flatpak edition's entry.
fn write_unless_flatpak(path: &Path, content: &str) -> std::io::Result<()> {
    if owned_by_flatpak(path) {
        return Ok(());
    }
    write_if_changed(path, content)
}

/// [`remove_if_present`] that never removes the Flatpak edition's entry.
fn remove_unless_flatpak(path: &Path) -> std::io::Result<()> {
    if owned_by_flatpak(path) {
        return Ok(());
    }
    remove_if_present(path)
}

fn remove_if_present(path: &Path) -> std::io::Result<()> {
    match std::fs::remove_file(path) {
        Err(e) if e.kind() != std::io::ErrorKind::NotFound => Err(e),
        _ => Ok(()),
    }
}

/// Creates (`enabled`) or removes the login entry for the running executable. `config` is the
/// `--config` path of a non-default profile: that profile gets its own entry (see
/// [`entry_name`]) which starts it, and disabling removes exactly that entry, wherever the
/// executable was when it was written.
///
/// A no-op in packaged editions: a LaunchAgent cannot work in the Mac App Store sandbox, and an
/// MSIX run key would persist the versioned `WindowsApps` path (MSIX users enable the declared
/// startup task in Windows Settings instead).
///
/// The Flatpak edition asks the Background portal instead (`config_dir` holds its marker, `rt`
/// drives the D-Bus call; both are unused elsewhere).
pub fn apply(
    enabled: bool,
    config: Option<&Path>,
    config_dir: &Path,
    rt: &tokio::runtime::Handle,
) -> std::io::Result<()> {
    let ch = siple_core::config::channel::current();
    let portal = || {
        #[cfg(target_os = "linux")]
        return super::portal_background::sync(enabled, config, config_dir, rt);
        #[cfg(not(target_os = "linux"))]
        {
            let _ = (config_dir, rt);
            Ok(())
        }
    };
    dispatch(ch, portal, || apply_for(ch, enabled, config))
}

/// Picks the Background portal for the Flatpak edition and the file/registry entry for the rest.
fn dispatch(
    c: &siple_core::config::channel::Channel,
    portal: impl FnOnce() -> std::io::Result<()>,
    entry: impl FnOnce() -> std::io::Result<()>,
) -> std::io::Result<()> {
    if uses_portal(c) { portal() } else { entry() }
}

/// Whether the login entry goes through the Background portal (the Flatpak edition).
fn uses_portal(c: &siple_core::config::channel::Channel) -> bool {
    c.kind == siple_core::config::channel::ChannelKind::Flatpak
}

fn apply_for(
    channel: &siple_core::config::channel::Channel,
    enabled: bool,
    config: Option<&Path>,
) -> std::io::Result<()> {
    if channel.is_packaged() {
        tracing::info!(
            channel = channel.kind.as_str(),
            enabled,
            "launch at login is managed by the OS for this edition; nothing to do"
        );
        return Ok(());
    }
    // The AppImage edition starts its file, never the temporary mount the process runs from.
    let exe = channel.launch_target()?;
    let extra = profile_args(config);
    let name = entry_name(config);
    #[cfg(target_os = "windows")]
    {
        use winreg::RegKey;
        use winreg::enums::{HKEY_CURRENT_USER, KEY_SET_VALUE};
        let (key, _) = RegKey::predef(HKEY_CURRENT_USER).create_subkey_with_flags(
            r"Software\Microsoft\Windows\CurrentVersion\Run",
            KEY_SET_VALUE,
        )?;
        if enabled {
            key.set_value(&name, &windows_run_value(&exe, &extra))
        } else {
            match key.delete_value(&name) {
                Err(e) if e.kind() != std::io::ErrorKind::NotFound => Err(e),
                _ => Ok(()),
            }
        }
    }
    #[cfg(not(target_os = "windows"))]
    {
        let macos = cfg!(target_os = "macos");
        let path = entry_path(
            dirs::home_dir().as_deref(),
            dirs::config_dir().as_deref(),
            macos,
            &name,
        )
        .ok_or_else(|| std::io::Error::other("cannot determine the autostart directory"))?;
        if enabled {
            let content = if macos {
                macos_launch_agent(&name, &macos_program_args(&exe, &extra))
            } else {
                linux_autostart_entry(&exe, &extra)
            };
            write_unless_flatpak(&path, &content)
        } else {
            remove_unless_flatpak(&path)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn packaged_editions_write_no_login_entry() {
        use siple_core::config::channel::Channel;
        #[cfg(not(target_os = "windows"))]
        let entry = entry_path(
            dirs::home_dir().as_deref(),
            dirs::config_dir().as_deref(),
            cfg!(target_os = "macos"),
            &entry_name(None),
        );
        #[cfg(not(target_os = "windows"))]
        let before = entry.as_ref().map(|p| p.exists());
        for ch in [Channel::MAC_APP_STORE, Channel::msix("a_b", None)] {
            assert!(apply_for(&ch, true, None).is_ok());
            assert!(apply_for(&ch, false, None).is_ok());
        }
        #[cfg(not(target_os = "windows"))]
        assert_eq!(entry.as_ref().map(|p| p.exists()), before);
    }

    #[test]
    fn the_appimage_login_entry_starts_the_file() {
        use siple_core::config::channel::Channel;
        let ch = Channel::appimage(Path::new("/home/u/My Apps/Siple.AppImage"));
        assert!(!ch.is_packaged() && !uses_portal(&ch));
        let entry = linux_autostart_entry(&ch.launch_target().unwrap(), &[]);
        assert!(
            entry.contains("Exec=\"/home/u/My Apps/Siple.AppImage\""),
            "{entry}"
        );
    }

    #[test]
    fn only_the_flatpak_uses_the_background_portal() {
        use siple_core::config::channel::Channel;
        assert!(uses_portal(&Channel::FLATPAK));
        for ch in [
            Channel::DIRECT,
            Channel::MAC_APP_STORE,
            Channel::msix("a_b", None),
        ] {
            assert!(!uses_portal(&ch));
        }
    }

    #[test]
    fn apply_goes_through_the_portal_only_in_the_flatpak() {
        use siple_core::config::channel::Channel;
        use std::cell::Cell;
        for (ch, via_portal) in [
            (Channel::FLATPAK, true),
            (Channel::DIRECT, false),
            (Channel::MAC_APP_STORE, false),
        ] {
            let (p, e) = (Cell::new(0), Cell::new(0));
            dispatch(
                &ch,
                || {
                    p.set(p.get() + 1);
                    Ok(())
                },
                || {
                    e.set(e.get() + 1);
                    Ok(())
                },
            )
            .unwrap();
            assert_eq!((p.get(), e.get()), if via_portal { (1, 0) } else { (0, 1) });
        }
    }

    #[test]
    fn plist_is_well_formed_and_escaped() {
        let p = macos_launch_agent(
            APP_ID,
            &["/Applications/A & B/Siple.app".into(), "--x<y".into()],
        );
        assert!(p.starts_with("<?xml"));
        assert!(p.contains("<key>Label</key>"));
        assert!(p.contains("<string>io.zyno.siple</string>"));
        assert!(p.contains("<string>/Applications/A &amp; B/Siple.app</string>"));
        assert!(p.contains("<string>--x&lt;y</string>"));
        assert!(p.contains("<key>RunAtLoad</key>\n    <true/>"));
        assert!(p.trim_end().ends_with("</plist>"));
    }

    #[test]
    fn macos_args_use_open_inside_a_bundle() {
        assert_eq!(
            macos_program_args(
                Path::new("/Applications/Siple.app/Contents/MacOS/siple"),
                &[]
            ),
            vec!["/usr/bin/open", "-a", "/Applications/Siple.app"]
        );
        assert_eq!(
            macos_program_args(Path::new("/usr/local/bin/siple"), &[]),
            vec!["/usr/local/bin/siple"]
        );
        let extra = profile_args(Some(Path::new("/p/work.toml")));
        assert_eq!(extra, vec!["--config", "/p/work.toml"]);
        assert_eq!(
            macos_program_args(
                Path::new("/Applications/Siple.app/Contents/MacOS/siple"),
                &extra
            ),
            vec![
                "/usr/bin/open",
                "-a",
                "/Applications/Siple.app",
                "--args",
                "--config",
                "/p/work.toml"
            ]
        );
        assert_eq!(
            macos_program_args(Path::new("/usr/local/bin/siple"), &extra),
            vec!["/usr/local/bin/siple", "--config", "/p/work.toml"]
        );
        assert!(profile_args(None).is_empty());
    }

    #[test]
    fn desktop_exec_quoting() {
        assert_eq!(desktop_exec_quote("/usr/bin/siple"), "/usr/bin/siple");
        let q = desktop_exec_quote("/tmp/a\nX-Flatpak=io.zyno.siple\r");
        assert!(!q.contains('\n') && !q.contains('\r'), "{q}");
        assert_eq!(q, "\"/tmp/a\\nX-Flatpak=io.zyno.siple\\r\"");
        assert_eq!(
            desktop_exec_quote("/opt/my apps/siple"),
            "\"/opt/my apps/siple\""
        );
        // Exec quoting plus the key's string escaping: two backslashes before `$`, four before `\`.
        assert_eq!(desktop_exec_quote("/a/$b"), "\"/a/\\\\$b\"");
        assert_eq!(desktop_exec_quote("/a b\\c"), "\"/a b\\\\\\\\c\"");
        assert_eq!(desktop_exec_quote("/a/100%"), "\"/a/100%%\"");
        let e = linux_autostart_entry(Path::new("/opt/my apps/siple"), &[]);
        assert!(e.starts_with("[Desktop Entry]\nType=Application\n"));
        assert!(e.contains("Exec=\"/opt/my apps/siple\"\n"));
        assert!(e.contains("X-GNOME-Autostart-enabled=true"));
        let e = linux_autostart_entry(
            Path::new("/usr/bin/siple"),
            &profile_args(Some(Path::new("/home/a/my profile.toml"))),
        );
        assert!(
            e.contains("Exec=/usr/bin/siple --config \"/home/a/my profile.toml\"\n"),
            "{e}"
        );
    }

    #[test]
    fn windows_value_is_quoted() {
        assert_eq!(
            windows_run_value(Path::new(r"C:\Program Files\Siple\siple.exe"), &[]),
            r#""C:\Program Files\Siple\siple.exe""#
        );
        assert_eq!(
            windows_run_value(
                Path::new(r"C:\Siple\siple.exe"),
                &profile_args(Some(Path::new(r"C:\Users\a b\c.toml")))
            ),
            r#""C:\Siple\siple.exe" "--config" "C:\Users\a b\c.toml""#
        );
    }

    #[test]
    fn each_profile_has_its_own_entry_name() {
        // The default profile keeps the plain id.
        assert_eq!(entry_name(None), "io.zyno.siple");
        let a = entry_name(Some(Path::new("/p/a.toml")));
        let b = entry_name(Some(Path::new("/p/b.toml")));
        assert!(
            a.starts_with("io.zyno.siple-") && a.len() == "io.zyno.siple-".len() + 8,
            "{a}"
        );
        assert_ne!(a, b);
        // Stable between runs (it is the name of a file / registry value).
        assert_eq!(a, entry_name(Some(Path::new("/p/a.toml"))));
        assert_eq!(
            entry_path(Some(Path::new("/Users/a")), None, true, &a),
            Some(PathBuf::from(format!(
                "/Users/a/Library/LaunchAgents/{a}.plist"
            )))
        );
        let p = macos_launch_agent(&a, &["/x".into()]);
        assert!(p.contains(&format!("<string>{a}</string>")));
    }

    #[test]
    fn entry_paths() {
        assert_eq!(
            entry_path(Some(Path::new("/Users/a")), None, true, APP_ID),
            Some(PathBuf::from(
                "/Users/a/Library/LaunchAgents/io.zyno.siple.plist"
            ))
        );
        assert_eq!(
            entry_path(None, Some(Path::new("/home/a/.config")), false, APP_ID),
            Some(PathBuf::from(
                "/home/a/.config/autostart/io.zyno.siple.desktop"
            ))
        );
        assert_eq!(entry_path(None, None, true, APP_ID), None);
    }

    #[test]
    fn the_tarball_leaves_the_flatpaks_login_entry_alone() {
        let portal = "[Desktop Entry]\nType=Application\nName=Siple\n\
            Exec=flatpak run --command=siple io.zyno.siple\nX-Flatpak=io.zyno.siple\n";
        assert!(is_flatpak_entry(portal));
        assert!(is_flatpak_entry("[Desktop Entry]\nX-Flatpak-Foo=1\n"));
        assert!(is_flatpak_entry(
            "[Desktop Entry]\nExec=flatpak run io.zyno.siple\n"
        ));
        assert!(!is_flatpak_entry(&linux_autostart_entry(
            Path::new("/usr/bin/siple"),
            &[]
        )));

        let d = tempfile::tempdir().unwrap();
        let f = d.path().join("autostart/io.zyno.siple.desktop");
        std::fs::create_dir_all(f.parent().unwrap()).unwrap();
        std::fs::write(&f, portal).unwrap();
        write_unless_flatpak(&f, "tarball").unwrap();
        assert_eq!(std::fs::read_to_string(&f).unwrap(), portal);
        remove_unless_flatpak(&f).unwrap();
        assert_eq!(std::fs::read_to_string(&f).unwrap(), portal);

        // The tarball's own entry is still written and removed.
        let own = linux_autostart_entry(Path::new("/usr/bin/siple"), &[]);
        std::fs::write(&f, &own).unwrap();
        write_unless_flatpak(&f, "new").unwrap();
        assert_eq!(std::fs::read_to_string(&f).unwrap(), "new");
        remove_unless_flatpak(&f).unwrap();
        assert!(!f.exists());
        write_unless_flatpak(&f, &own).unwrap();
        assert_eq!(std::fs::read_to_string(&f).unwrap(), own);
    }

    #[test]
    fn write_and_remove_use_the_filesystem_idempotently() {
        let d = tempfile::tempdir().unwrap();
        let f = d.path().join("sub/x.desktop");
        write_if_changed(&f, "a").unwrap();
        let m1 = std::fs::metadata(&f).unwrap().modified().unwrap();
        write_if_changed(&f, "a").unwrap();
        assert_eq!(std::fs::metadata(&f).unwrap().modified().unwrap(), m1);
        write_if_changed(&f, "b").unwrap();
        assert_eq!(std::fs::read_to_string(&f).unwrap(), "b");
        // Removal does not depend on what the entry says (the exe may have moved since).
        remove_if_present(&f).unwrap();
        remove_if_present(&f).unwrap();
        assert!(!f.exists());
    }
}
